import json
from pathlib import Path
import tempfile
import unittest
from unittest import mock

from genie.json import make_json


class FakeDistribution:
    def __init__(self, direct_url_text, location):
        self.direct_url_text = direct_url_text
        self.location = location

    def read_text(self, name):
        if name == 'direct_url.json':
            return self.direct_url_text
        return None

    def locate_file(self, _path):
        return self.location


class TestGetPackageLocation(unittest.TestCase):
    @mock.patch.object(make_json, 'distribution')
    def test_get_package_location_uses_editable_direct_url(
        self, mock_distribution
    ):
        with tempfile.TemporaryDirectory() as directory:
            repo = Path(directory) / 'genieparser'
            repo.mkdir()
            direct_url_text = json.dumps({
                'url': repo.as_uri(),
                'dir_info': {'editable': True},
            })
            mock_distribution.return_value = FakeDistribution(
                direct_url_text, Path(directory)
            )
            self.assertEqual(
                make_json.get_package_location('genie.libs.parser'),
                str(repo.resolve()),
            )

    @mock.patch.object(make_json, 'distribution')
    def test_get_package_location_keeps_legacy_fallback(
        self, mock_distribution
    ):
        with tempfile.TemporaryDirectory() as directory:
            site_packages = (
                Path(directory) / 'venv' / 'lib' / 'python3.14' / 'site-packages'
            )
            site_packages.mkdir(parents=True)
            mock_distribution.return_value = FakeDistribution(None, site_packages)
            self.assertEqual(
                make_json.get_package_location('genie.libs.parser'),
                str(site_packages.resolve().parent),
            )
